import{_ as t,o as r,c as i,a3 as l}from"./chunks/framework.DBpCFmh2.js";const b=JSON.parse('{"title":"进程管理","description":"本文聚焦 Agent 端的进程管理能力，围绕命令执行、Shell 选择、环境变量白名单、运行监控、优雅与强制终止、进程树清理、生命周期与资源回收等主题展开。","frontmatter":{"title":"进程管理","description":"本文聚焦 Agent 端的进程管理能力，围绕命令执行、Shell 选择、环境变量白名单、运行监控、优雅与强制终止、进程树清理、生命周期与资源回收等主题展开。"},"headers":[],"relativePath":"本地代理服务/命令执行引擎/进程管理/index.md","filePath":"本地代理服务/命令执行引擎/进程管理/index.md","lastUpdated":null}'),a={name:"本地代理服务/命令执行引擎/进程管理/index.md"};function s(n,e,o,c,h,u){return r(),i("div",null,[...e[0]||(e[0]=[l(`<h1 id="进程管理" tabindex="-1">进程管理 <a class="header-anchor" href="#进程管理" aria-label="Permalink to &quot;进程管理&quot;">​</a></h1><details class="details custom-block"><summary>本文引用的源码文件</summary><p><strong>本文引用的文件</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js" target="_blank" rel="noreferrer">agent/src/executor.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js" target="_blank" rel="noreferrer">agent/src/process-tree.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js" target="_blank" rel="noreferrer">agent/src/security.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js" target="_blank" rel="noreferrer">agent/bin/agent.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js" target="_blank" rel="noreferrer">agent/src/server.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/executor-shell.unit.test.js" target="_blank" rel="noreferrer">agent/test/unit/executor-shell.unit.test.js</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/process-tree.unit.test.js" target="_blank" rel="noreferrer">agent/test/unit/process-tree.unit.test.js</a></li></ul></details><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="#引言">引言</a></li><li><a href="#项目结构">项目结构</a></li><li><a href="#核心组件">核心组件</a></li><li><a href="#架构总览">架构总览</a></li><li><a href="#详细组件分析">详细组件分析</a></li><li><a href="#依赖关系分析">依赖关系分析</a></li><li><a href="#性能与资源特性">性能与资源特性</a></li><li><a href="#故障排查指南">故障排查指南</a></li><li><a href="#结论">结论</a></li><li><a href="#附录api-与使用建议">附录：API 与使用建议</a></li></ol><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to &quot;引言&quot;">​</a></h2><p>本文聚焦 Agent 端的进程管理能力，围绕命令执行、Shell 选择、环境变量白名单、运行监控、优雅与强制终止、进程树清理、生命周期与资源回收等主题展开。Agent 采用双进程架构：Chrome 扩展端通过本地 HTTP/WebSocket 调用 Agent；Agent 内部通过 Node.js child_process 派生子进程执行命令，并提供 WebSocket 流式输出、超时策略、安全分级与跨平台兼容处理。</p><h2 id="项目结构" tabindex="-1">项目结构 <a class="header-anchor" href="#项目结构" aria-label="Permalink to &quot;项目结构&quot;">​</a></h2><p>与进程管理直接相关的代码主要分布在以下模块：</p><ul><li>agent/src/executor.js：命令执行器，负责 Shell 选择、子进程创建、输出缓冲、WebSocket 流式广播、超时策略、进程停止与查询。</li><li>agent/src/process-tree.js：进程树终止工具，提供整树 SIGTERM/SIGKILL 能力与优雅等待。</li><li>agent/src/security.js：安全管控（路径沙箱与命令分级），对危险命令进行黑名单/灰名单拦截。</li><li>agent/bin/agent.js：CLI 入口，负责 Agent 进程启停、健康检查、PID 管理与跨平台终止。</li><li>agent/src/server.js：HTTP + WebSocket 服务，聚合 executor、security、process-tree 等能力对外暴露 API。</li></ul><pre class="mermaid">graph TB
subgraph &quot;扩展端&quot;
BG[&quot;background/tool-executor.js&lt;br/&gt;扩展侧工具执行&quot;]
end
subgraph &quot;Agent 进程&quot;
CLI[&quot;agent/bin/agent.js&lt;br/&gt;CLI 启动/停止/重启&quot;]
SRV[&quot;agent/src/server.js&lt;br/&gt;HTTP + WebSocket 路由&quot;]
EXEC[&quot;agent/src/executor.js&lt;br/&gt;命令执行器&quot;]
PTREE[&quot;agent/src/process-tree.js&lt;br/&gt;进程树终止&quot;]
SEC[&quot;agent/src/security.js&lt;br/&gt;路径沙箱 + 命令分级&quot;]
end
OS[&quot;操作系统 / Shell&lt;br/&gt;Git Bash / PowerShell / cmd / zsh / bash&quot;]
BG --&gt; |HTTP/WebSocket| SRV
CLI --&gt; |spawn/kill| SRV
SRV --&gt; EXEC
SRV --&gt; SEC
SRV --&gt; PTREE
EXEC --&gt; OS
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L302-L384" target="_blank" rel="noreferrer">agent/bin/agent.js#L302-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L30" target="_blank" rel="noreferrer">agent/src/server.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L1-L10" target="_blank" rel="noreferrer">agent/src/process-tree.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L302-L384" target="_blank" rel="noreferrer">agent/bin/agent.js#L302-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L30" target="_blank" rel="noreferrer">agent/src/server.js#L1-L30</a></li></ul><h2 id="核心组件" tabindex="-1">核心组件 <a class="header-anchor" href="#核心组件" aria-label="Permalink to &quot;核心组件&quot;">​</a></h2><ul><li>命令执行器（executor.js）：实现 Shell 选择、安全环境变量构建、子进程创建、输出流式广播、超时策略、进程停止与运行状态查询。</li><li>进程树工具（process-tree.js）：封装跨平台整树终止逻辑，支持 SIGTERM → 延迟 → SIGKILL 的优雅关闭流程。</li><li>安全管控（security.js）：路径白名单/硬阻止与命令分级（黑名单 deny、灰名单 confirm、允许 allow）。</li><li>CLI 入口（agent/bin/agent.js）：负责 Agent 进程守护、健康检查、PID 文件、优雅/强制终止与跨平台兼容。</li><li>服务端（server.js）：聚合上述能力，对外暴露 HTTP/WebSocket 接口，并设置语言上下文。</li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L73</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L229" target="_blank" rel="noreferrer">agent/src/security.js#L62-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L167-L188" target="_blank" rel="noreferrer">agent/bin/agent.js#L167-L188</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L30" target="_blank" rel="noreferrer">agent/src/server.js#L1-L30</a></li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><p>下图展示一次命令执行的端到端流程：扩展端发起请求，Agent 服务端校验安全策略后调度执行器，执行器选择 Shell、构建环境、派生子进程，并通过 WebSocket 流式推送 stdout/stderr，同时维护超时与终止策略。</p><pre class="mermaid">sequenceDiagram
participant Ext as &quot;扩展端&quot;
participant Srv as &quot;Agent 服务端(server.js)&quot;
participant Sec as &quot;安全管控(security.js)&quot;
participant Exec as &quot;命令执行器(executor.js)&quot;
participant PT as &quot;进程树(process-tree.js)&quot;
participant OS as &quot;系统 Shell&quot;
Ext-&gt;&gt;Srv : &quot;POST /api/exec(command, cwd, timeoutMs?)&quot;
Srv-&gt;&gt;Sec : &quot;checkCommand(command, force)&quot;
Sec--&gt;&gt;Srv : &quot;{safe, level, reason}&quot;
alt 允许或用户已确认
Srv-&gt;&gt;Exec : &quot;executeCommand(command, cwd, wsClient, opts)&quot;
Exec-&gt;&gt;Exec : &quot;pickShell() + buildSafeEnv()&quot;
Exec-&gt;&gt;OS : &quot;spawn(shell, args, {env, detached, windowsHide})&quot;
OS--&gt;&gt;Exec : &quot;stdout/stderr 事件&quot;
Exec--&gt;&gt;Srv : &quot;WS 广播 stdout/stderr/exit/error&quot;
Note over Exec,PT : &quot;超时到期或显式 kill → 优雅→强制终止&quot;
else 拒绝或需确认
Srv--&gt;&gt;Ext : &quot;错误/确认提示&quot;
end
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L30" target="_blank" rel="noreferrer">agent/src/server.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L685-L758" target="_blank" rel="noreferrer">agent/src/security.js#L685-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L73</a></li></ul><h2 id="详细组件分析" tabindex="-1">详细组件分析 <a class="header-anchor" href="#详细组件分析" aria-label="Permalink to &quot;详细组件分析&quot;">​</a></h2><h3 id="shell-选择与环境变量白名单" tabindex="-1">Shell 选择与环境变量白名单 <a class="header-anchor" href="#shell-选择与环境变量白名单" aria-label="Permalink to &quot;Shell 选择与环境变量白名单&quot;">​</a></h3><ul><li>Shell 选择逻辑（纯函数 pickShell）： <ul><li>Windows：优先检测 SHELL 是否为 Git Bash/Powershell/cmd 且存在；否则回退到常见 Git Bash 安装路径；若仍不可用则回退 COMSPEC 或 cmd.exe。</li><li>macOS：优先 SHELL 中的 zsh/bash，否则默认 /bin/zsh。</li><li>Linux：优先 SHELL 中的 bash/zsh/fish，否则探测 /bin/bash、/usr/bin/bash、/bin/sh，最终兜底 /bin/sh。</li></ul></li><li>环境变量白名单（SAFE_ENV_KEYS）：仅透传 PATH、HOME、USER、SHELL、LANG、COMSPEC、PSModulePath、JAVA_HOME、PYTHONPATH 等必要键，避免泄露宿主敏感信息；强制 TERM=dumb、FORCE_COLOR=0。</li></ul><pre class="mermaid">flowchart TD
Start([&quot;进入 pickShell&quot;]) --&gt; CheckWin{&quot;平台为 Windows?&quot;}
CheckWin --&gt; |是| WinCheck[&quot;检查 SHELL 是否包含 bash/powershell/cmd 且存在&quot;]
WinCheck --&gt; |命中| UseShell[&quot;返回 shell + 对应参数&quot;]
WinCheck --&gt; |未命中| TryGitBash[&quot;尝试常见 Git Bash 路径&quot;]
TryGitBash --&gt; FoundGB{&quot;找到 Git Bash?&quot;}
FoundGB --&gt; |是| UseShell
FoundGB --&gt; |否| UseCmd[&quot;回退 COMSPEC 或 cmd.exe&quot;]
CheckWin --&gt; |否| CheckMac{&quot;平台为 macOS?&quot;}
CheckMac --&gt; |是| MacCheck[&quot;检查 SHELL 是否包含 zsh/bash 且存在&quot;]
MacCheck --&gt; |命中| UseShell
MacCheck --&gt; |未命中| DefaultZsh[&quot;默认 /bin/zsh&quot;]
CheckMac --&gt; |否| LinCheck[&quot;检查 SHELL 是否包含 bash/zsh/fish 且存在&quot;]
LinCheck --&gt; |命中| UseShell
LinCheck --&gt; |未命中| ProbeSh[&quot;探测 /bin/bash -&gt; /usr/bin/bash -&gt; /bin/sh&quot;]
ProbeSh --&gt; FoundSh{&quot;找到任一?&quot;}
FoundSh --&gt; |是| UseShell
FoundSh --&gt; |否| Fallback[&quot;兜底 /bin/sh&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/executor-shell.unit.test.js#L11-L56" target="_blank" rel="noreferrer">agent/test/unit/executor-shell.unit.test.js#L11-L56</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/executor-shell.unit.test.js#L58-L104" target="_blank" rel="noreferrer">agent/test/unit/executor-shell.unit.test.js#L58-L104</a></li></ul><h3 id="进程创建与运行监控" tabindex="-1">进程创建与运行监控 <a class="header-anchor" href="#进程创建与运行监控" aria-label="Permalink to &quot;进程创建与运行监控&quot;">​</a></h3><ul><li>子进程创建： <ul><li>使用 spawn(shell, [...args, command])，根据平台与 shell 类型决定是否 detached 与 windowsHide。</li><li>标准输出/错误以 pipe 方式读取，按 execId 广播给所有 WebSocket 客户端。</li></ul></li><li>运行状态跟踪： <ul><li>runningProcesses 映射记录 execId → {process, wsClients, stdoutBuf, stderrBuf, startTime, baseTimeout, managed, extensions, outputInPeriod, detached, timedOut}。</li><li>completedProcesses 缓存已完成进程的输出与退出码，供延迟连接的 WS 客户端回放。</li></ul></li><li>资源使用与异常检测： <ul><li>输出缓冲区上限 MAX_OUTPUT_BUFFER = 5MB，超过时截断并广播 truncated 消息。</li><li>超时策略：受管模式（传入 timeoutMs）下依据 decideTimeoutAction 决策延长或终止；旧模式直接终止。</li><li>进程 close/error 事件统一清理定时器、移出 runningProcesses、写入 completedProcesses 并回调 onComplete。</li></ul></li></ul><pre class="mermaid">flowchart TD
A[&quot;executeCommand 开始&quot;] --&gt; B[&quot;生成 execId&quot;]
B --&gt; C[&quot;pickShell + buildSafeEnv&quot;]
C --&gt; D[&quot;spawn(shell, args, env, stdio, detached/windowsHide)&quot;]
D --&gt; E[&quot;注册 stdout/stderr 监听&quot;]
E --&gt; F[&quot;广播 stdout/stderr 片段&quot;]
F --&gt; G{&quot;收到输出?&quot;}
G --&gt; |是| H[&quot;标记 outputInPeriod=true&quot;]
G --&gt; |否| I[&quot;保持静默&quot;]
H --&gt; J[&quot;armTimeout(timeout)&quot;]
I --&gt; J
J --&gt; K{&quot;超时到达?&quot;}
K --&gt; |是| L[&quot;decideTimeoutAction 决策&quot;]
L --&gt; |extend| M[&quot;延长定时器&quot;]
L --&gt; |kill| N[&quot;killProcess(execId)&quot;]
K --&gt; |否| O[&quot;继续运行&quot;]
O --&gt; P[&quot;close/error 事件&quot;]
P --&gt; Q[&quot;清理定时器/移出 runningProcesses/写入 completedProcesses&quot;]
Q --&gt; R[&quot;onComplete 回调&quot;]
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L386" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L386</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L429-L479" target="_blank" rel="noreferrer">agent/src/executor.js#L429-L479</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L555-L568" target="_blank" rel="noreferrer">agent/src/executor.js#L555-L568</a></li></ul><h3 id="进程终止策略与跨平台兼容" tabindex="-1">进程终止策略与跨平台兼容 <a class="header-anchor" href="#进程终止策略与跨平台兼容" aria-label="Permalink to &quot;进程终止策略与跨平台兼容&quot;">​</a></h3><ul><li>优雅关闭（SIGTERM）： <ul><li>POSIX：优先向进程组发送 SIGTERM（-pid），失败时回退单进程 kill。</li><li>Windows：taskkill /T /PID 递归终止整个进程树。</li></ul></li><li>强制终止（SIGKILL）： <ul><li>POSIX：5 秒后向进程组发送 SIGKILL，再失败回退单进程。</li><li>Windows：taskkill /F /T /PID 强制终止整棵树。</li></ul></li><li>进程树清理： <ul><li>process-tree.js 提供 killProcessTree 与 stopProcessTree，后者在 graceMs 后升级 SIGKILL，并保证 close/error 不永久挂起。</li></ul></li><li>CLI 层终止： <ul><li>agent/bin/agent.js 的 killByPid 在 Windows 使用 taskkill /F /T，POSIX 使用 process.kill(pid, &#39;SIGTERM&#39;)。</li></ul></li></ul><pre class="mermaid">flowchart TD
S[&quot;stopProcessTree(child, graceMs)&quot;] --&gt; T{&quot;child.pid 有效?&quot;}
T --&gt; |否| End[&quot;立即 resolve&quot;]
T --&gt; |是| U[&quot;注册 close/error 完成回调&quot;]
U --&gt; V[&quot;killProcessTree(SIGTERM)&quot;]
V --&gt; W[&quot;graceMs 后 killProcessTree(SIGKILL)&quot;]
W --&gt; X[&quot;hardTimer(graceMs+5s) 兜底完成&quot;]
X --&gt; End
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L50-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L50-L73</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L42" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L42</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L495-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L495-L549</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L167-L188" target="_blank" rel="noreferrer">agent/bin/agent.js#L167-L188</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L73</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L495-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L495-L549</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L167-L188" target="_blank" rel="noreferrer">agent/bin/agent.js#L167-L188</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/process-tree.unit.test.js#L56-L88" target="_blank" rel="noreferrer">agent/test/unit/process-tree.unit.test.js#L56-L88</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/test/unit/process-tree.unit.test.js#L90-L118" target="_blank" rel="noreferrer">agent/test/unit/process-tree.unit.test.js#L90-L118</a></li></ul><h3 id="安全管控与命令分级" tabindex="-1">安全管控与命令分级 <a class="header-anchor" href="#安全管控与命令分级" aria-label="Permalink to &quot;安全管控与命令分级&quot;">​</a></h3><ul><li>路径沙箱： <ul><li>硬阻止目录（HARD_BLOCKED_PATHS）：Agent 配置、日志、回收站等关键路径不可访问。</li><li>工作目录放行：workdir 始终可访问，但 realpath 仍需过硬阻止检查。</li><li>allowedPaths 前缀匹配 + realpath 校验，防止符号链接绕过。</li></ul></li><li>命令分级： <ul><li>黑名单（deny）：高危破坏性命令绝对禁止，force 不可绕过。</li><li>灰名单（confirm）：sudo、rm -rf、chmod 777、网络外联、脚本解释器等需用户确认。</li><li>白名单（allow）：普通只读或低风险命令。</li><li>链式命令拆分、包装器剥壳、内联载荷解析、命令替换扫描，确保复杂命令不被绕过。</li></ul></li></ul><pre class="mermaid">flowchart TD
A[&quot;checkCommand(command, force)&quot;] --&gt; B[&quot;collectCommandScopes(原始串 + 拆分段 + 内联载荷)&quot;]
B --&gt; C{&quot;命中黑名单?&quot;}
C --&gt; |是| Deny[&quot;level=&#39;deny&#39;&quot;]
C --&gt; |否| D{&quot;force=true?&quot;}
D --&gt; |是| Allow[&quot;level=&#39;allow&#39;&quot;]
D --&gt; |否| E{&quot;命中灰名单?&quot;}
E --&gt; |是| Confirm[&quot;level=&#39;confirm&#39;&quot;]
E --&gt; |否| Allow
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L685-L758" target="_blank" rel="noreferrer">agent/src/security.js#L685-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L392-L683" target="_blank" rel="noreferrer">agent/src/security.js#L392-L683</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L62-L229" target="_blank" rel="noreferrer">agent/src/security.js#L62-L229</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L285-L384" target="_blank" rel="noreferrer">agent/src/security.js#L285-L384</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L392-L683" target="_blank" rel="noreferrer">agent/src/security.js#L392-L683</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L685-L758" target="_blank" rel="noreferrer">agent/src/security.js#L685-L758</a></li></ul><h3 id="进程生命周期管理" tabindex="-1">进程生命周期管理 <a class="header-anchor" href="#进程生命周期管理" aria-label="Permalink to &quot;进程生命周期管理&quot;">​</a></h3><ul><li>进程池管理： <ul><li>runningProcesses 作为“运行中进程表”，completedProcesses 作为“已完成缓存”（TTL 30s）。</li><li>addWsClient/disconnectWsClient 支持动态加入/移除 WS 监听；断开连接时仅在非受管模式或显式 detach 才取消超时。</li></ul></li><li>资源回收： <ul><li>clearTimers 清理超时与强制终止定时器。</li><li>completedProcesses 条目在 TTL 后自动清理。</li></ul></li><li>僵尸进程清理： <ul><li>process-tree.js 的 stopProcessTree 保证 close/error 事件触发后不再等待，避免孤儿进程长期残留。</li></ul></li><li>内存泄漏防护： <ul><li>输出缓冲区上限截断 + trunc 标志广播。</li><li>受管模式下超时策略基于 decideTimeoutAction，避免无限延长。</li></ul></li></ul><pre class="mermaid">classDiagram
class Executor {
+executeCommand(command, cwd, wsClient, onComplete, collectOutput, execOpts) string
+executeCommandSync(command, cwd, timeoutMs) Promise
+addWsClient(execId, wsClient) boolean
+disconnectWsClient(execId, wsClient) boolean
+killProcess(execId) boolean
+detachProcess(execId) boolean
+getRunningProcesses() array
}
class ProcessTree {
+killProcessTree(child, signal) boolean
+stopProcessTree(child, options) Promise
}
class Security {
+checkCommand(command, force, tFn) object
+checkPath(pathStr, tFn) object
}
Executor --&gt; ProcessTree : &quot;终止策略&quot;
Executor --&gt; Security : &quot;命令安全校验&quot;
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L570" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L570</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L73</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L685-L758" target="_blank" rel="noreferrer">agent/src/security.js#L685-L758</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L570" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L570</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L73</a></li></ul><h2 id="依赖关系分析" tabindex="-1">依赖关系分析 <a class="header-anchor" href="#依赖关系分析" aria-label="Permalink to &quot;依赖关系分析&quot;">​</a></h2><ul><li>server.js 依赖 executor、security、process-tree，对外暴露 HTTP/WebSocket 接口。</li><li>executor 依赖 os、fs、crypto，内部使用 child_process.spawn 派生子进程。</li><li>process-tree 依赖 child_process.spawn 与 process.kill，封装跨平台终止逻辑。</li><li>security 依赖 path、fs/promises、os，实现路径与命令安全策略。</li><li>agent/bin/agent.js 依赖 child_process、fs、os，负责 CLI 与进程守护。</li></ul><pre class="mermaid">graph LR
Server[&quot;server.js&quot;] --&gt; Executor[&quot;executor.js&quot;]
Server --&gt; Security[&quot;security.js&quot;]
Server --&gt; ProcessTree[&quot;process-tree.js&quot;]
Executor --&gt; Child[&quot;child_process&quot;]
ProcessTree --&gt; Child
Security --&gt; PathFS[&quot;path/fs/promises/os&quot;]
CLI[&quot;agent/bin/agent.js&quot;] --&gt; Server
CLI --&gt; Child
</pre><p><strong>图表来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L30" target="_blank" rel="noreferrer">agent/src/server.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L1-L10" target="_blank" rel="noreferrer">agent/src/process-tree.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L1-L10" target="_blank" rel="noreferrer">agent/bin/agent.js#L1-L10</a></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/server.js#L1-L30" target="_blank" rel="noreferrer">agent/src/server.js#L1-L30</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L1-L10" target="_blank" rel="noreferrer">agent/src/executor.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L1-L10" target="_blank" rel="noreferrer">agent/src/process-tree.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L1-L10" target="_blank" rel="noreferrer">agent/src/security.js#L1-L10</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/bin/agent.js#L1-L10" target="_blank" rel="noreferrer">agent/bin/agent.js#L1-L10</a></li></ul><h2 id="性能与资源特性" tabindex="-1">性能与资源特性 <a class="header-anchor" href="#性能与资源特性" aria-label="Permalink to &quot;性能与资源特性&quot;">​</a></h2><ul><li>输出缓冲限制：MAX_OUTPUT_BUFFER = 5MB，避免长时间命令导致内存无限增长；超限时广播 truncated 消息。</li><li>超时策略： <ul><li>受管模式（execOpts.timeoutMs）：基于 decideTimeoutAction，期内有输出才延长，静默即杀；最大延长次数 MAX_TIMEOUT_EXTENSIONS = 5，总预算封顶 TOTAL_BUDGET_CAP_MS = 600000ms。</li><li>旧模式：到期直接 kill。</li></ul></li><li>进程树终止： <ul><li>POSIX 优先进程组信号，Windows 使用 taskkill /T /PID；5 秒后升级为 SIGKILL 或 /F /T /PID。</li></ul></li><li>资源回收： <ul><li>completedProcesses 缓存 TTL 30s，避免长期驻留；disconnectWsClient 在非受管模式或 detach 时才释放超时。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L93-L116" target="_blank" rel="noreferrer">agent/src/executor.js#L93-L116</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L297-L323" target="_blank" rel="noreferrer">agent/src/executor.js#L297-L323</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L459-L479" target="_blank" rel="noreferrer">agent/src/executor.js#L459-L479</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L495-L549" target="_blank" rel="noreferrer">agent/src/executor.js#L495-L549</a></li></ul><h2 id="故障排查指南" tabindex="-1">故障排查指南 <a class="header-anchor" href="#故障排查指南" aria-label="Permalink to &quot;故障排查指南&quot;">​</a></h2><ul><li>命令被拒绝： <ul><li>检查 security.js 的黑名单/灰名单规则；必要时通过前端确认流程（force）放行灰名单。</li></ul></li><li>命令无输出或卡住： <ul><li>检查 decideTimeoutAction 是否因静默而 kill；确认 WS 客户端是否正确订阅 stdout/stderr。</li></ul></li><li>进程未完全退出： <ul><li>使用 process-tree.js 的 stopProcessTree 确保 SIGTERM → SIGKILL 升级；Windows 下确认 taskkill /T /PID 生效。</li></ul></li><li>Shell 选择异常： <ul><li>在 Windows 上 SHELL 可能为 MSYS 风格路径（如 /usr/bin/bash），无法直接执行；pickShell 会回退到 Git Bash 或 cmd.exe。</li></ul></li><li>环境变量缺失导致工具失败： <ul><li>确认 SAFE_ENV_KEYS 是否包含所需键（如 JAVA_HOME、PYTHONPATH、PSModulePath 等）。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L685-L758" target="_blank" rel="noreferrer">agent/src/security.js#L685-L758</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L165-L186" target="_blank" rel="noreferrer">agent/src/executor.js#L165-L186</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L50-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L50-L73</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L32-L91" target="_blank" rel="noreferrer">agent/src/executor.js#L32-L91</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L118-L156" target="_blank" rel="noreferrer">agent/src/executor.js#L118-L156</a></li></ul><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>Agent 的进程管理以 executor.js 为核心，结合 process-tree.js 的跨平台终止能力与 security.js 的安全分级，实现了从 Shell 选择、环境变量白名单、运行监控到优雅/强制终止的完整闭环。CLI 层（agent/bin/agent.js）与 server.js 提供了进程守护与健康检查，确保扩展端与 Agent 端的稳定通信。建议在复杂任务中优先使用受管模式（timeoutMs）并结合 WS 流式输出进行实时监控，同时在安全敏感场景严格遵循黑名单/灰名单策略。</p><h2 id="附录-api-与使用建议" tabindex="-1">附录：API 与使用建议 <a class="header-anchor" href="#附录-api-与使用建议" aria-label="Permalink to &quot;附录：API 与使用建议&quot;">​</a></h2><ul><li>命令执行（Executor） <ul><li>executeCommand(command, cwd?, wsClient?, onComplete?, collectOutput?, execOpts?)</li><li>executeCommandSync(command, cwd?, timeoutMs?)</li><li>addWsClient(execId, wsClient)</li><li>disconnectWsClient(execId, wsClient)</li><li>killProcess(execId)</li><li>detachProcess(execId)</li><li>getRunningProcesses()</li></ul></li><li>进程树终止（ProcessTree） <ul><li>killProcessTree(child, signal?)</li><li>stopProcessTree(child, {graceMs?})</li></ul></li><li>安全策略（Security） <ul><li>checkCommand(command, force?, tFn?)</li><li>checkPath(pathStr, tFn?)</li></ul></li><li>使用建议 <ul><li>始终传入 execOpts.timeoutMs 启用受管模式，避免 SW 生命周期影响超时权威。</li><li>对高风险命令提前走确认流程，减少误报摩擦。</li><li>长耗时任务建议使用 WS 流式输出，并在断开连接时注意 detach 语义。</li></ul></li></ul><p><strong>章节来源</strong></p><ul><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/executor.js#L198-L570" target="_blank" rel="noreferrer">agent/src/executor.js#L198-L570</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/process-tree.js#L18-L73" target="_blank" rel="noreferrer">agent/src/process-tree.js#L18-L73</a></li><li><a href="https://github.com/xiweicheng/ai-helper/blob/main/agent/src/security.js#L685-L758" target="_blank" rel="noreferrer">agent/src/security.js#L685-L758</a></li></ul>`,80)])])}const p=t(a,[["render",s]]);export{b as __pageData,p as default};
